#!/bin/sh
# HMDFS fix: umask 077 创建目录后无法写入文件
# Workaround: sed config.status 中的 umask 077 → umask 002
# 用法: 在 configure 运行后、config.status 执行前运行此脚本
#
# 根因: HMDFS 文件系统在 umask 077 下创建的目录 (drwx--S---)
#       无法写入文件，即使是目录所有者也无法写入
# 影响: 所有 autotools 脚本 (configure + config.status) 的临时目录创建

# Fix config.status (generated by configure)
if [ -f config.status ]; then
    sed -i 's/umask 077/umask 002/g' config.status
fi

# Also fix configure itself if running from fresh extraction
if [ -f configure ]; then
    sed -i 's/umask 077/umask 002/g' configure
fi
